# Initially generated by GitHub Copilot.
"""Run one repo utility action across repos from a workspace file.

Usage examples:
    .venv/Scripts/python.exe py/main_repo_util.py --run-black
    .venv/Scripts/python.exe py/main_repo_util.py --audit-line-terms --today-only
    .venv/Scripts/python.exe py/main_repo_util.py --check-repo-standards --repos MAM-basics
    .venv/Scripts/python.exe py/main_repo_util.py --check-memory-health --workspace-file all-repos.code-workspace
    .venv/Scripts/python.exe py/main_repo_util.py --clean-worktrees --workspace-file all-repos.code-workspace
    .venv/Scripts/python.exe py/main_repo_util.py --commit-across-repos --message-file .novc/commit_msg_shared.txt --dry-run

``--workspace-file all-repos.code-workspace`` is what widens any of these past the
handful of repos ``MAM-basics.code-workspace`` lists, and is worth spelling out for
``--clean-worktrees``: the repos most in need of it are the ones with no Python and
so no maintenance script of their own (see ``repo_util/clean_worktrees.py``).

Three of the repos that file lists are private, so a sweep over all of them
produces findings that must not land in this public repo's tracked tree.
``--visibility`` splits the sweep, and is the intended shape of a full round of
maintenance -- two runs of each read-only action rather than one:

    ... --check-repo-standards --visibility public  --report-txt .novc/standards-public.txt
    ... --check-repo-standards --visibility private --report-txt ^
        C:/Users/BenDe/GitRepos/MAM-private/.novc/standards-private.txt

The default is ``all``, which still sweeps everything; what the default cannot do
is write its report into a file this repo tracks. See
``repo_util/report_destination.py`` for what is refused and why.
"""

from __future__ import annotations

import argparse
from pathlib import Path
from typing import Sequence

from mb_cmn import paths
from repo_util.audit_line_terms import run_audit_line_terms_across_repos
from repo_util.check_memory_health import run_check_memory_health_across_repos
from repo_util.check_repo_standards import run_check_repo_standards_across_repos
from repo_util.clean_worktrees import (
    problem_repos as worktree_problem_repos,
    run_clean_worktrees_across_repos,
)
from repo_util.commit_across_repos import run_commit_across_repos
from repo_util import maintenance_policy
from repo_util.report_destination import assert_report_destination_ok
from repo_util.repo_selection import load_workspace_repo_dirs, select_repo_infos
from repo_util.run_black import problem_repos, run_black_across_repos

REPO_ROOT = paths.repo_root()
DEFAULT_WORKSPACE_FILE = REPO_ROOT / "MAM-basics.code-workspace"


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)

    action_group = parser.add_mutually_exclusive_group(required=True)
    action_group.add_argument("--run-black", action="store_true")
    action_group.add_argument("--audit-line-terms", action="store_true")
    action_group.add_argument("--check-repo-standards", action="store_true")
    action_group.add_argument("--check-memory-health", action="store_true")
    action_group.add_argument("--clean-worktrees", action="store_true")
    action_group.add_argument("--commit-across-repos", action="store_true")

    parser.add_argument(
        "--workspace-file",
        default=str(DEFAULT_WORKSPACE_FILE),
        help="Path to the .code-workspace file listing repo folders",
    )
    parser.add_argument(
        "--repos-root",
        help="Optional base path used to resolve workspace folder paths",
    )
    parser.add_argument(
        "--repos",
        nargs="+",
        help="Optional explicit subset (repo names or paths)",
    )
    parser.add_argument(
        "--today-only",
        action="store_true",
        help="Keep only repos whose HEAD committer local date is today",
    )
    parser.add_argument(
        "--visibility",
        choices=("all", "public", "private"),
        default="all",
        help=(
            "Keep only repos of this visibility, per in/repo_maintenance_policy.json."
            " Use it to split a report in two so the private half never reaches this"
            " public repo's tree (default: all)"
        ),
    )

    parser.add_argument(
        "--black-target",
        default=".",
        help="Target passed to black when --run-black is used",
    )
    parser.add_argument(
        "--black-timeout-sec",
        type=float,
        help="Optional timeout in seconds for each repo black run",
    )
    parser.add_argument(
        "--include-pattern",
        default="*.py",
        help="Pattern(s) used by git ls-files for line-term audits (comma-separated)",
    )
    parser.add_argument(
        "--exclude-novc",
        dest="exclude_novc",
        action="store_true",
        default=True,
        help="Exclude files under .novc/ during line-term audits (default)",
    )
    parser.add_argument(
        "--include-novc",
        dest="exclude_novc",
        action="store_false",
        help="Include files under .novc/ during line-term audits",
    )
    parser.add_argument(
        "--exclude-dot-venv",
        dest="exclude_dot_venv",
        action="store_true",
        default=True,
        help="Exclude files under .venv/ during line-term audits (default)",
    )
    parser.add_argument(
        "--include-dot-venv",
        dest="exclude_dot_venv",
        action="store_false",
        help="Include files under .venv/ during line-term audits",
    )
    parser.add_argument(
        "--exclude-novc-prefix",
        dest="exclude_novc_prefix",
        action="store_true",
        default=True,
        help="Exclude tracked files named novc*.py during line-term audits (default)",
    )
    parser.add_argument(
        "--include-novc-prefix",
        dest="exclude_novc_prefix",
        action="store_false",
        help="Include tracked files named novc*.py during line-term audits",
    )

    parser.add_argument(
        "--report-json",
        help=(
            "Write JSON report for --run-black, --audit-line-terms,"
            " --check-repo-standards or --check-memory-health"
        ),
    )
    parser.add_argument(
        "--report-txt",
        help=(
            "Write text report for --run-black, --audit-line-terms,"
            " --check-repo-standards or --check-memory-health"
        ),
    )

    message_group = parser.add_mutually_exclusive_group(required=False)
    message_group.add_argument(
        "--message",
        help="Commit message text reused in every committed repo",
    )
    message_group.add_argument(
        "--message-file",
        help="Path to a UTF-8 text file whose content is the commit message",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="With --commit-across-repos, show what would be committed",
    )
    parser.add_argument(
        "--and-push",
        action="store_true",
        help="With --commit-across-repos, push each successfully committed repo",
    )

    return parser


def _validate_action_specific_args(
    parser: argparse.ArgumentParser, args: argparse.Namespace
) -> None:
    if args.commit_across_repos:
        if args.message is None and args.message_file is None:
            parser.error(
                "--commit-across-repos requires one of --message or --message-file"
            )
        return

    if args.message is not None or args.message_file is not None:
        parser.error("--message/--message-file only apply to --commit-across-repos")
    if args.dry_run:
        parser.error("--dry-run only applies to --commit-across-repos")
    if args.and_push:
        parser.error("--and-push only applies to --commit-across-repos")


def _filter_by_visibility(repo_infos, visibility: str):
    """Keep the repos of the requested visibility, failing loudly on an unclassified one.

    A repo missing from in/repo_maintenance_policy.json's repo_visibility map is
    an error rather than a default, because both plausible defaults are wrong:
    treating it as public would let its findings through the guard, and treating
    it as private would silently drop it from the public half of every report.
    py/tests/test_repo_visibility_declared.py catches this before a sweep does.
    """
    if visibility == "all":
        return repo_infos
    declared = maintenance_policy.repo_visibility()
    unclassified = sorted(info.name for info in repo_infos if info.name not in declared)
    if unclassified:
        raise KeyError(
            "Repo(s) with no visibility declared in in/repo_maintenance_policy.json:"
            f" {', '.join(unclassified)}. Add an entry for each before using"
            " --visibility."
        )
    return [info for info in repo_infos if declared[info.name] == visibility]


def main(argv: Sequence[str] | None = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    _validate_action_specific_args(parser, args)

    workspace_file = Path(args.workspace_file).resolve()
    repos_root = (
        Path(args.repos_root).resolve()
        if args.repos_root is not None
        else workspace_file.parent
    )

    repo_infos = select_repo_infos(
        workspace_file,
        repos_root=repos_root,
        repos=args.repos,
        today_only=args.today_only,
    )
    # Kept before any filtering, because --check-memory-health resolves a cited
    # path against the whole workspace rather than against the selection. See
    # run_check_memory_health_across_repos' docstring for the measured figures.
    workspace_repo_dirs = load_workspace_repo_dirs(workspace_file, repos_root)
    repo_infos = _filter_by_visibility(repo_infos, args.visibility)
    if not repo_infos:
        print(
            "No repos selected after applying workspace/repo/date/visibility filters."
        )
        return 0

    report_json = Path(args.report_json).resolve() if args.report_json else None
    report_txt = Path(args.report_txt).resolve() if args.report_txt else None

    # Before any sweep runs, not after: a refusal that arrives once the findings
    # are already gathered still tempts whoever sees it to paste them somewhere.
    private = maintenance_policy.private_repos()
    covered = [info.name for info in repo_infos]
    for path, option_name in (
        (report_json, "--report-json"),
        (report_txt, "--report-txt"),
    ):
        assert_report_destination_ok(
            path,
            covered_repo_names=covered,
            private_repo_names=private,
            option_name=option_name,
        )

    if args.run_black:
        # Kept although it normally matches nothing now: the frozen repos are in
        # no workspace file, and a sweep can only reach the repos a workspace
        # file lists, so this skip never fires. It stays as the backstop for a
        # frozen repo that does turn up in a workspace file. There is no override
        # any more -- --include-frozen was removed on 2026-08-07, having become a
        # way to ask for repos the sweep could no longer see. Absence from the
        # workspace file, NOT a repo's location on disk, is what enforces the
        # freeze; the C:/Users/BenDe/FrozenRepos directory that once held these
        # clones is retired and is not expected on any machine, per Ben's
        # decision of 2026-08-31 recorded in in/repo_maintenance_policy.json's
        # location_comment.
        frozen = maintenance_policy.frozen_repos()
        results = run_black_across_repos(
            repo_infos,
            black_target=args.black_target,
            black_timeout_sec=args.black_timeout_sec,
            frozen_repos=frozen,
            vendored_package_names=maintenance_policy.vendored_package_names(),
            vendored_overrides=maintenance_policy.vendored_overrides(),
            source_repo=REPO_ROOT,
            report_json=report_json,
            report_txt=report_txt,
        )
        # Every repo the sweep could format has been formatted by now: a repo it
        # could not is reported and then fails the run, rather than being passed
        # over in silence. A repo with no tracked .py files is not a problem.
        return 1 if problem_repos(results) else 0

    if args.audit_line_terms:
        run_audit_line_terms_across_repos(
            repo_infos,
            include_pattern=args.include_pattern,
            exclude_novc=args.exclude_novc,
            exclude_dot_venv=args.exclude_dot_venv,
            exclude_novc_prefix=args.exclude_novc_prefix,
            report_json=report_json,
            report_txt=report_txt,
        )
        return 0

    if args.check_repo_standards:
        run_check_repo_standards_across_repos(
            repo_infos,
            exclude_novc=args.exclude_novc,
            exclude_dot_venv=args.exclude_dot_venv,
            report_json=report_json,
            report_txt=report_txt,
        )
        return 0

    if args.check_memory_health:
        run_check_memory_health_across_repos(
            repo_infos,
            report_json=report_json,
            report_txt=report_txt,
            resolution_repo_dirs=workspace_repo_dirs,
        )
        return 0

    if args.clean_worktrees:
        # Same contract as --run-black: a repo the sweep could not clean fails
        # the run rather than being passed over. A worktree deliberately spared
        # is not a failure -- see repo_util/clean_worktrees.py.
        reports = run_clean_worktrees_across_repos(repo_infos)
        return 1 if worktree_problem_repos(reports) else 0

    run_commit_across_repos(
        repo_infos,
        message=args.message,
        message_file=args.message_file,
        dry_run=args.dry_run,
        and_push=args.and_push,
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
